import { readFile } from 'node:fs/promises';

export const VIN_PROFILE_REGISTRY_VERSION = 'vin-profiles.v1';
const ARTIFACT = new URL('../../data/gcsp/vehicle-evidence/vin-profiles.v1.json', import.meta.url);
