import { readSync, readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const gate = Buffer.alloc(1);
if (readSync(0, gate, 0, 1, null) !== 1 || gate[0] !== 49) throw new Error('Supervisor gate refused');
